let current = 'zh-CN';

function setLocale(l) { current = STRINGS[l] ? l : 'en'; document.documentElement.lang = current; }
function getLocale() { return current; }

function t(key, vars) {
  let s = (STRINGS[current] && STRINGS[current][key]) || STRINGS.en[key] || key;
  if (current === 'en' && vars && (vars.n === 1 || (vars.n === undefined && vars.count === 1)) && SINGULAR_EN[key]) s = SINGULAR_EN[key];
  return vars ? s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined ? m : vars[k])) : s;
}

// Fill every [data-i18n] element (text) and [data-i18n-title] (tooltip).
function applyStatic(root = document) {
  for (const el of root.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  for (const el of root.querySelectorAll('[data-i18n-title]')) el.title = t(el.dataset.i18nTitle);
  for (const el of root.querySelectorAll('[data-i18n-placeholder]')) el.placeholder = t(el.dataset.i18nPlaceholder);
  for (const el of root.querySelectorAll('[data-i18n-aria]')) el.setAttribute('aria-label', t(el.dataset.i18nAria));
}

